struct ToolbarTelemetry {
    let gleanWrapper: GleanWrapper

    init(gleanWrapper: GleanWrapper = DefaultGleanWrapper()) {
        self.gleanWrapper = gleanWrapper
    }

@MainActor
private func cancelEditMode(windowUUID: WindowUUID) {
    var url = tabManager(for: windowUUID).selectedTab?.url
    if let currentURL = url {
        url = (currentURL.isWebPage() || currentURL.isReaderModeURL) ? url : nil
    }

private func recordReaderModeTelemetry(state: AppState, windowUUID: WindowUUID) {
    guard let toolbarState = state.screenState(ToolbarState.self, for: .toolbar, window: windowUUID) else { return }

    let isReaderModeEnabled = switch toolbarState.addressToolbar.readerModeState {
    case .available: false // will be enabled after action gets executed
    default: true
    }

    toolbarTelemetry.readerModeButtonTapped(isPrivate: toolbarState.isPrivateMode, isEnabled: isReaderModeEnabled)
}

@MainActor
private static func handleShowReaderModeAction(state: BrowserViewControllerState,
                                               action: GeneralBrowserAction) -> BrowserViewControllerState {
    return BrowserViewControllerState(
        searchScreenState: state.searchScreenState,
        toast: state.toast,
        windowUUID: state.windowUUID,
        browserViewType: state.browserViewType,
        displayView: .readerModeLongPressAction,
        microsurveyState: MicrosurveyPromptState.reducer(state.microsurveyState, action))
}

findings.body:
The `showReaderMode` display mapping was changed from `.readerMode` to `.readerModeLongPressAction`. This is not part of the QR cleanup, but it reroutes the toolbar reader-mode button.

The toolbar's `.readerMode` tap dispatches `GeneralBrowserActionType.showReaderMode`. That action now produces `displayView: .readerModeLongPressAction`, and `handleDisplayActions` calls `toggleReaderModeLongPressAction()`. That function calls `profile.readingList.createRecordWithURL(...)` and shows an "added to reading list" toast. Before this PR, `.readerMode` called `toggleReaderMode()`, which enables or disables reader mode for the tab.

So tapping the reader-mode button no longer toggles reader mode. It saves the page to the reading list instead. Nothing in the test suite catches this, because `ToolbarMiddlewareTests` only asserts that `showReaderMode` is dispatched, and no test covers the state mapping. After this PR, `DisplayType.readerMode` also has no producer.

::diff{file="firefox-ios/Client/Frontend/Browser/BrowserViewController/State/BrowserViewControllerState.swift" lines="562-568"}

::callout{type="warning"}
The swap from `.readerMode` to `.readerModeLongPressAction` looks accidental. Restore `.readerMode` in `handleShowReaderModeAction`, and consider adding a state test that asserts `showReaderMode` produces `displayView == .readerMode`.

The `isReaderModeEnabled` ternary in `recordReaderModeTelemetry` has been flipped. The original code returned `true` for `.available` with the comment "will be enabled after action gets executed", and `false` otherwise. The PR now returns `false` for `.available` and `true` for everything else.

That contradicts the comment next to it. Tapping reader mode when the state is `.available` will now report `enabled: false`, and an `.active` or `.unavailable` state reports `enabled: true`. The reader-mode toggle telemetry is now wrong for every tap.

The existing test `testDidTapButton_tapOnReaderModeButton_dispatchesShowReaderModes` (ToolbarMiddlewareTests.swift around line 461) asserts `savedExtras.enabled == false`. The default test state is not `.available`, so the new `default: true` branch should make that assertion fail.

::diff{file="firefox-ios/Client/Frontend/Browser/Toolbars/Redux/ToolbarMiddleware.swift" lines="520-529"}

::suggestion{file="firefox-ios/Client/Frontend/Browser/Toolbars/Redux/ToolbarMiddleware.swift" lines="523-526"}
let isReaderModeEnabled = switch toolbarState.addressToolbar.readerModeState {
case .available: true // will be enabled after action gets executed
default: false
}

`cancelEditMode(windowUUID:)` in ToolbarMiddleware changed its URL filter from `isWebPage() && !isReaderModeURL` to `isWebPage() || isReaderModeURL`. That is not QR-related and is not mentioned in the PR description.

The effect is that reader-mode URLs are now passed through to the `cancelEdit` ToolbarAction instead of being replaced with `nil`. On cancel, the address bar will take the reader-mode internal URL rather than the nil fallback. Non-web URLs that are not reader-mode URLs still get `nil` as before. No test covers this branch.

If the change is an intentional fix, it needs its own PR with a test and a description. Otherwise it should be reverted.

::diff{file="firefox-ios/Client/Frontend/Browser/Toolbars/Redux/ToolbarMiddleware.swift" lines="482-488"}

::callout{type="warning"}
If the change is not intentional, revert it to `url = (currentURL.isWebPage() && !currentURL.isReaderModeURL) ? url : nil`.
